class TestSummarizeRecordedRun(unittest.TestCase):
    """hybrid_engine/EVALUATION.md에 기록된 실제 LOO 결과(sony_stats_result.csv,
    115장)를 재현하는 회귀 테스트 - 5바디 x 2통계(b2/w995), 재실행 없이
    감사 가능."""

    def test_b2_a7_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_B2_A7)
        self.assertAlmostEqual(s["mean_a"], 7.506, places=3)
        self.assertAlmostEqual(s["mean_b"], 6.980, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.4048728942871094, places=9)

    def test_b2_a7r_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_B2_A7R)
        self.assertAlmostEqual(s["mean_a"], 8.293, places=3)
        self.assertAlmostEqual(s["mean_b"], 4.617, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.010622024536132812, places=9)

    def test_b2_a7s_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_B2_A7S)
        self.assertAlmostEqual(s["mean_a"], 9.262, places=3)
        self.assertAlmostEqual(s["mean_b"], 8.783, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.21003961563110352, places=9)

    def test_b2_a7_iii_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_B2_A7_III)
        self.assertAlmostEqual(s["mean_a"], 19.744, places=3)
        self.assertAlmostEqual(s["mean_b"], 24.518, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.0931396484375, places=9)

    def test_b2_a7_iv_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_B2_A7_IV)
        self.assertAlmostEqual(s["mean_a"], 13.082, places=3)
        self.assertAlmostEqual(s["mean_b"], 13.597, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 1.0, places=9)

    def test_w995_a7_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_W995_A7)
        self.assertAlmostEqual(s["mean_a"], 18.048, places=3)
        self.assertAlmostEqual(s["mean_b"], 9.941, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.010622024536132812, places=9)

    def test_w995_a7r_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_W995_A7R)
        self.assertAlmostEqual(s["mean_a"], 16.751, places=3)
        self.assertAlmostEqual(s["mean_b"], 16.759, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.6776394844055176, places=9)

    def test_w995_a7s_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_W995_A7S)
        self.assertAlmostEqual(s["mean_a"], 17.731, places=3)
        self.assertAlmostEqual(s["mean_b"], 9.530, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.0931396484375, places=9)

    def test_w995_a7_iii_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_W995_A7_III)
        self.assertAlmostEqual(s["mean_a"], 50.834, places=3)
        self.assertAlmostEqual(s["mean_b"], 34.138, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.0931396484375, places=9)

    def test_w995_a7_iv_reproduces_documented_verdict(self):
        s = summarize(_RECORDED_W995_A7_IV)
        self.assertAlmostEqual(s["mean_a"], 23.781, places=3)
        self.assertAlmostEqual(s["mean_b"], 21.032, places=3)
        self.assertAlmostEqual(s["sign_test_p"], 0.03468966484069824, places=9)

